import React, { useState, useEffect } from "react";
import "./VendorDashboard.css";
import { getProductsByVendor, createProduct, updateProduct, deleteProductById, getOrdersByVendor, updateOrderStatus } from "../utils/api";
import { jsxDEV as _jsxDEV } from "react/jsx-dev-runtime";
export default function VendorDashboard({
  vendor,
  onLogout
}) {
  _s();
  const [products, setProducts] = useState([]);
  const [orders, setOrders] = useState([]);
  const [form, setForm] = useState({
    id: null,
    name: "",
    description: "",
    price: "",
    stockQuantity: "",
    category: "",
    imageUrl: ""
  });
  const [editing, setEditing] = useState(false);

  // Fetch products and orders
  const fetchProducts = async () => {
    if (!vendor) return;
    const data = await getProductsByVendor(vendor.id);
    setProducts(data);
  };
  const fetchOrders = async () => {
    if (!vendor) return;
    const data = await getOrdersByVendor(vendor.id);
    setOrders(data);
  };
  useEffect(() => {
    fetchProducts();
    fetchOrders();
  }, [vendor]);

  // Product form handling
  const handleChange = e => {
    const {
      name,
      value
    } = e.target;
    setForm({
      ...form,
      [name]: value
    });
  };
  const handleSubmit = async e => {
    e.preventDefault();
    try {
      if (editing) {
        await updateProduct(form.id, {
          ...form,
          vendor
        });
      } else {
        await createProduct({
          ...form,
          vendor
        });
      }
      setForm({
        id: null,
        name: "",
        description: "",
        price: "",
        stockQuantity: "",
        category: "",
        imageUrl: ""
      });
      setEditing(false);
      fetchProducts();
    } catch (err) {
      console.error(err);
      alert("Error saving product");
    }
  };
  const handleEdit = product => {
    setForm(product);
    setEditing(true);
  };
  const handleDelete = async id => {
    if (window.confirm("Are you sure?")) {
      await deleteProductById(id);
      fetchProducts();
    }
  };

  // Update order status
  const handleStatusChange = async (orderId, newStatus) => {
    try {
